body='''export type ActivityRecordInput = {
  actorId: UserId | null;
  subjectKind: ActivitySubjectKind;
  subjectId: string;
  projectId: ProjectId | null;
  summary: string;
  metadata?: Readonly<Record<string, string | number | boolean | null>>;
  /**
   * When the action happened. Event handlers pass the payload's stamp so a
   * row written late (a job catching up, a slow handler) still files under
   * the moment of the action; omitted, it defaults to "now".
   */
  occurredAt?: IsoTimestamp | string;
};

/** Filter for a whole-range read: everything but the paging fields. */
type ActivityRangeFilter = Omit<ActivityFilterInput, "limit" | "cursor">;

/** Columns of the audit-log CSV export, in the order the file lists them. */
const EXPORT_COLUMNS = [
  "occurredAt",
  "action",
  "actorId",
  "subjectKind",
  "subjectId",
  "summary",
] as const;

/** Rows fetched per round trip while an export walks the whole range. */
const EXPORT_BATCH_SIZE = 100;

/**
 * Appends one audit row. Deliberately takes no `Actor`: the writer is usually
 * an event handler running outside a request, and the row's `actorId` comes
 * from the event payload rather than from an authenticated principal.
 */
export async function record(
  orgId: OrgId,
  action: ActivityAction,
  input: ActivityRecordInput,
): Promise<ActivityEvent> {
  return activityRepo.insertActivity({
    orgId,
    action,
    actorId: input.actorId,
    subjectKind: input.subjectKind,
    subjectId: input.subjectId,
    projectId: input.projectId,
    summary: input.summary,
    metadata: input.metadata ?? {},
    occurredAt: stampOf(input.occurredAt),
  });
}

export async function listActivity(
  actor: Actor,
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:read", activityResource(input.orgId));
  assertOrderedRange(input.since, input.until);
  return activityRepo.listActivity(input);
}

/**
 * Every row matching `filter`, newest first, walking the keyset pages until
 * the range is exhausted. This is what an export reads — a single page would
 * silently truncate the audit trail.
 */
export async function listAllActivity(
  actor: Actor,
  filter: ActivityRangeFilter,
): Promise<readonly ActivityEvent[]> {
  assertOrgScope(actor, filter.orgId);
  assertCan(actor, "activity:export", activityResource(filter.orgId));
  assertOrderedRange(filter.since, filter.until);
  return collectActivity(filter);
}

/** Groups a feed page by calendar day, newest day first. */
export function groupByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = event.occurredAt.slice(0, 10);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => (a < b ? 1 : -1))
    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
}

/**
 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
 * for the role, and on the `csv_export` flag for the plan.
 */
export async function exportActivity(
  actor: Actor,
  input: ExportActivityInput,
): Promise<string> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));
  assertOrderedRange(input.since, input.until);

  const org = await orgRepo.findOrgById(input.orgId);
  const flagEnabled = isEnabled("csv_export", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.format === "csv" && !flagEnabled) {
    throw new Error("CSV export is not included in this plan");
  }

  const events = await collectActivity({
    orgId: input.orgId,
    since: input.since,
    until: input.until,
  });

  if (input.format === "json") {
    return JSON.stringify(events, null, 2);
  }

  return toCsv(
    events.map((event) => ({
      occurredAt: event.occurredAt,
      action: event.action,
      actorId: event.actorId,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      summary: event.summary,
    })),
    [...EXPORT_COLUMNS],
  );
}

async function collectActivity(
  filter: ActivityRangeFilter,
): Promise<readonly ActivityEvent[]> {
  const events: ActivityEvent[] = [];
  let cursor: string | null = null;

  do {
    const page: Page<ActivityEvent> = await activityRepo.listActivity({
      ...filter,
      limit: EXPORT_BATCH_SIZE,
      cursor,
    });
    events.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  return events;
}

/** Refuses a range that ends before it starts; both ends are inclusive. */
function assertOrderedRange(
  since: string | null | undefined,
  until: string | null | undefined,
): void {
  if (isOrderedRange(since, until)) return;
  throw new ZodError([
    {
      code: "custom",
      path: ["until"],
      message: "until must not be earlier than since",
      input: until,
    },
  ]);
}

/** Normalises an event stamp; a missing or unparseable one falls back to now. */
function stampOf(value: string | undefined): IsoTimestamp {
  if (value !== undefined) {
    const date = new Date(value);
    if (!Number.isNaN(date.getTime())) return toIsoTimestamp(date);
  }
  return toIsoTimestamp(new Date());
}

/**
 * Comment events name the issue, not the project; the audit row needs the
 * project so a per-project feed includes the thread. Archived issues still
 * resolve — a comment can outlive its issue's archival.
 */
async function projectOfIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<ProjectId | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  return issue?.projectId ?? null;
}

