import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit, onHandlerError } from "@/lib/event-bus";
import * as activity from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let detach: () => void;
const errors: unknown[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("actcheck", "growth");
  detach = activity.registerActivityListeners();
  onHandlerError((t, e) => errors.push([t, e]));
});
afterAll(() => { detach(); cleanup(); });

describe("activity", () => {
  it("records everything", async () => {
    const other = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id, name: "Other", slug: "other", key: "OTH", description: null,
      visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
    });
    await projectService.updateProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: tenant.project.id, name: "Renamed" });
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "A" }));
    await issueService.updateIssue(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, title: "B" });
    await issueService.changeIssueStatus(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, status: "in_progress" });
    await issueService.assignIssue(tenant.actors.admin, { orgId: tenant.org.id, issueId: issue.id, assigneeId: tenant.userIds.member });
    const c = await commentService.createComment(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] });
    await commentService.updateComment(tenant.actors.member, { orgId: tenant.org.id, commentId: c.id, body: "hi2" });
    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: c.id });
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, issue.id);
    await projectService.archiveProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: other.id, archiveIssues: true });
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, other.id);
    await orgService.updateOrganization(tenant.actors.owner, { orgId: tenant.org.id, name: "New name" } as never);
    const members = await memberService.listMembers(tenant.actors.owner, { orgId: tenant.org.id, limit: 10 } as never);
    const viewer = members.items.find((m) => m.role === "viewer")!;
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer.id });

    const page = await activity.listActivity(tenant.actors.admin, { orgId: tenant.org.id, projectId: tenant.project.id, limit: 100, cursor: null });
    const actions = page.items.map((e) => e.action).sort();
    console.log(actions);
    const assigned = page.items.find((e) => e.action === "issue.assigned")!;
    expect(assigned.actorId).toBe(tenant.userIds.admin);
    const all = await activity.listActivity(tenant.actors.admin, { orgId: tenant.org.id, limit: 100, cursor: null });
    console.log(all.items.map((e) => `${e.action} ${e.actorId} ${e.projectId} ${JSON.stringify(e.metadata)}`));
